const METHOD_INFO = {
  einkochen: { icon: '🍯', label: 'Einkochen/Einwecken', tip: 'Im Glas mit Deckel bei ca. 90–100°C im Wasserbad oder Backofen sterilisieren – so hält sich z. B. Mus, Kompott oder Sugo mehrere Monate im Vorratsschrank.' },
  einfrieren: { icon: '❄️', label: 'Einfrieren', tip: 'Portionsweise in Gefrierbeuteln oder -dosen einfrieren. Viele Gemüsesorten vorher kurz blanchieren, damit Farbe, Biss und Vitamine besser erhalten bleiben.' },
  fermentieren: { icon: '🫙', label: 'Fermentieren', tip: 'Milchsäurevergärung in Salzlake (z. B. Sauerkraut, fermentierte Rote Bete) macht haltbar und probiotisch wertvoll – wichtig ist, dass alles komplett von Flüssigkeit bedeckt bleibt.' },
  trocknen: { icon: '🌾', label: 'Trocknen/Dörren', tip: 'An der Luft, im Backofen bei niedriger Temperatur oder im Dörrautomaten trocknen, bis kein Wasser mehr enthalten ist. Danach luftdicht und dunkel lagern.' },
  einlegen: { icon: '🥒', label: 'Einlegen', tip: 'In Essigsud, Salzlake oder Öl eingelegt hält sich Gemüse mehrere Monate im Glas – beliebt z. B. für Gewürzgurken, Essigzwiebeln oder Kräuter in Öl.' },
  lagern: { icon: '🧊', label: 'Kühl & dunkel lagern', tip: 'Kühl, dunkel und meist mit etwas Luftfeuchtigkeit lagern (Keller, Erdmiete oder Gemüsefach) – so bleiben viele Wurzel- und Knollengemüse wochen- bis monatelang frisch.' },
  marmelade: { icon: '🍓', label: 'Marmelade/Mus/Chutney', tip: 'Mit Zucker bzw. Gelierzucker eingekocht und heiß ins Glas gefüllt hält sich Marmelade, Mus oder Chutney bei ungeöffnetem Glas viele Monate.' },
  saft: { icon: '🧃', label: 'Saft/Sirup', tip: 'Entsaften und den Saft heiß abfüllen (oder zu Sirup einkochen) – so bleibt er in Flasche bzw. Glas mehrere Monate haltbar.' },
};

