const SYMPTOMS = [
  { label: 'Blätter gelb / hellgelb', cause: 'Nährstoffmangel (meist Stickstoff oder Eisen), Staunässe, oder zu wenig Licht.', fix: 'Stickstoffdünger geben, Drainage prüfen, ggf. Standort wechseln. Bei Chlorose (Adern grün, Fläche gelb): Eisenchelat-Dünger.' },
  { label: 'Blätter kräuseln / wellen sich', cause: 'Blattläuse (Unterseite), Virusinfektion, zu viel/wenig Wasser, oder Herbizidschäden.', fix: 'Blattunterseite kontrollieren. Bei Läusen: Seifenlauge oder Neemöl. Bei Virusinfektion: Pflanze entfernen, Werkzeug desinfizieren.' },
  { label: 'Braune Blattränder / -spitzen', cause: 'Zu wenig Wasser, zu trockene Luft, Salzstress durch Überdüngung oder Kalk im Gießwasser.', fix: 'Regelmäßiger gießen, Regenwasser verwenden. Boden ausspülen bei Überdüngung. Luftfeuchtigkeit erhöhen.' },
  { label: 'Weiße/graue Beläge auf Blättern', cause: 'Echter Mehltau (weißer pudrig) oder Falscher Mehltau (grau-violett, Unterseite).', fix: 'Echter Mehltau: Backpulver-Spray (1 TL / 500ml) oder Milch-Wasser (1:8). Falscher Mehltau: Kupferfungizid, befallene Blätter entfernen.' },
  { label: 'Schwarze Flecken auf Blättern', cause: 'Pilzerkrankung (Alternaria, Septoria), bakterielle Infektion, oder Sonnenbrand.', fix: 'Befallene Blätter entfernen und vernichten. Kupferspray auftragen. Nicht von oben gießen. Pflanzabstand vergrößern.' },
  { label: 'Blätter werden schlaff / hängen', cause: 'Wassermangel, Wurzelfäule, oder Fusarium/Verticillium-Welke (Pilz im Leitgewebe).', fix: 'Erst gießen beobachten: erholt sich die Pflanze? Nein → Wurzeln prüfen. Faule Wurzeln: weniger gießen, Drainage. Welke-Pilze: Pflanze entfernen.' },
  { label: 'Löcher in Blättern', cause: 'Schnecken (unregelmäßige Lochfraß), Raupen (Kohlweißling etc.), Käfer (Erdflöhe: kleine runde Löcher).', fix: 'Schnecken: Kaffeesatz, Schneckenkorn (bio). Raupen absammeln. Erdflöhe: feines Netz, Steinmehl, Knoblauchbrühe.' },
  { label: 'Blätter rollen sich ein', cause: 'Schutzreaktion bei Hitzestress oder Trockenheit, aber auch durch Blattrollvirus (Kartoffel, Tomate).', fix: 'Gießen erhöhen, Sonnenschutz. Bei Virus: Pflanze entfernen, Blattläuse bekämpfen (Überträger).' },
  { label: 'Früchte platzen auf / reißen', cause: 'Ungleichmäßige Bewässerung – nach Trockenheit kommt viel Wasser → Frucht wächst zu schnell.', fix: 'Gleichmäßig gießen, Mulchschicht anlegen, um Bodenfeuchte zu halten.' },
  { label: 'Früchte haben braune/schwarze Stellen (Blütenende)', cause: 'Blütenendfäule (BER) – Kalziummangel durch ungleichmäßige Wasserversorgung.', fix: 'Regelmäßig gießen, Calciumdünger sprühen. Nicht zu viel Stickstoff düngen.' },
  { label: 'Früchte bleiben klein / verkümmert', cause: 'Bestäubungsprobleme, Nährstoffmangel, zu viele Früchte an einer Pflanze.', fix: 'Blüten leicht schütteln (Bestäubung). Ausgeizen bei Tomaten. Kalium-Dünger in der Fruchtphase.' },
  { label: 'Silbrige/fleckige Blattoberfläche', cause: 'Thripse (kleine Insekten saugen Zellsaft), Spinnmilben (trockene Bedingungen).', fix: 'Blatt-Unterseite kontrollieren (Gespinst → Spinnmilben). Raubmilben einsetzen, Neemöl sprühen, Luftfeuchtigkeit erhöhen.' },
];

